import numpy as np
from scipy.optimize import brentq
# Check if (C) and (D) are equivalent (define same psi-vs-phi)
alpha=np.radians(30); beta=np.radians(50); gamma=np.radians(70)
def Ceq(psi,phi):
    return np.sin(gamma)*np.sin(beta-phi)*np.sin(alpha+gamma-psi) - np.sin(beta)*np.sin(gamma-psi)*np.sin(alpha+beta-phi)
def Deq(psi,phi):
    return np.sin(gamma)*np.sin(phi)*np.sin(alpha+psi) - np.sin(beta)*np.sin(psi)*np.sin(alpha+phi)
for phi_deg in [15,20,25,30,35,40]:
    phi=np.radians(phi_deg)
    try:
        psi_C=brentq(Ceq, 0.01, gamma-0.01, args=(phi,))
        psi_D=brentq(Deq, 0.01, gamma-0.01, args=(phi,))
        print(f"phi={phi_deg}: psi from C={np.degrees(psi_C):.6f}, psi from D={np.degrees(psi_D):.6f}, diff={abs(psi_C-psi_D):.2e}")
    except Exception as ex:
        print(f"phi={phi_deg}: err {ex}")
