import numpy as np
from scipy.optimize import brentq
def angle_between(u,v):
    cu=np.dot(u,v)/(np.linalg.norm(u)*np.linalg.norm(v))
    return np.arccos(np.clip(cu,-1,1))
def Cval(alpha,beta,phi,psi):
    gamma=np.pi-2*alpha-beta
    return np.sin(gamma)*np.sin(beta-phi)*np.sin(alpha+gamma-psi) - np.sin(beta)*np.sin(gamma-psi)*np.sin(alpha+beta-phi)
# Check psi>phi for D near A and near BC, for several triangles
for alpha_deg,beta_deg in [(30,50),(20,60),(35,45),(15,75),(40,40)]:
    alpha=np.radians(alpha_deg); beta=np.radians(beta_deg)
    gamma=np.pi-2*alpha-beta
    if not(gamma>beta and 0<beta<np.pi/2 and 0<gamma<np.pi/2 and 0<2*alpha<np.pi/2): 
        print(f"a={alpha_deg} b={beta_deg}: invalid (g={np.degrees(gamma):.1f})"); continue
    # phi ranges (0,beta). For each phi, psi from C=0. Check psi>phi and E,F on segment.
    oops=False
    for phi_deg in np.linspace(1,beta_deg-1,8):
        phi=np.radians(phi_deg)
        try:
            psi=brentq(lambda ps: Cval(alpha,beta,phi,ps), 0.01, gamma-0.01)
        except: continue
        if psi<=phi: oops=True; print(f"  a={alpha_deg} b={beta_deg} phi={phi_deg:.1f}: psi={np.degrees(psi):.3f} <= phi!")
    if not oops: print(f"a={alpha_deg} b={beta_deg} g={np.degrees(gamma):.1f}: psi>phi for all tested phi OK")
